// @defer: load heavy chart component only when in viewport
@defer (on viewport) {
  <heavy-chart [data]="chartData()" />
} @placeholder {
  <div class="chart-skeleton" style="height: 300px"></div>
} @loading (minimum 500ms) {
  <spinner />
} @error {
  <p>Failed to load chart</p>
}

// @defer with condition (signal or expression)
@defer (when isExpanded()) {
  <detailed-view [item]="selected()" />
}

// Pure custom pipe (runs only when value reference changes)
@Pipe({ name: 'fileSize', pure: true })
export class FileSizePipe implements PipeTransform {
  transform(bytes: number): string {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
  }
}

// async pipe — subscribe in template, auto-unsubscribe
@Component({
  template: `
    @if (user$ | async; as user) {
      <p>Welcome, {{ user.name }}</p>
    } @else {
      <p>Loading...</p>
    }
  `
})
export class ProfileComponent {
  user$ = this.userService.getCurrentUser();
  constructor(private userService: UserService) {}
}

// ng-template + ngTemplateOutlet for reusable fragments
@Component({
  template: \`
    <ng-template #avatarTpl let-user="user">
      <img [src]="user.avatar" [alt]="user.name">
    </ng-template>
    <ng-container *ngTemplateOutlet="avatarTpl; context: {user: currentUser()}"></ng-container>
    <ng-container *ngTemplateOutlet="avatarTpl; context: {user: selectedUser()}"></ng-container>
  \`
})
export class AvatarExample { currentUser = signal<User|null>(null); selectedUser = signal<User|null>(null); }
